{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/patterns/action-group.json
    One or two calls to action side by side: a filled primary button and an outline secondary one. Links, not handlers: the page decides what they open.
    Props (p): primary, primaryHref, secondary, secondaryHref, align. -#}
{%- set v_primary = (p.primary ?? null) -%}
{%- set v_primaryHref = (p.primaryHref ?? null) -%}
{%- set v_secondary = (p.secondary ?? null) -%}
{%- set v_secondaryHref = (p.secondaryHref ?? null) -%}
{%- set v_align = (p.align ?? 'start') -%}
{%- set c_3 -%}
  {%- set c_1 -%}
    {{ ui_text(v_primary) }}
  {%- endset -%}
  {{ include('ui/button/button.html.twig', {'p': {'Variant': 'default', 'Size': 'default', 'Href': ui_s(v_primaryHref), 'Attrs': ui_attrs(['data-testid', 'action-primary'])}, 'children': c_1}, with_context = false) }}
  {%- if ui_t(v_secondary) %}
    {%- set c_2 -%}
      {{ ui_text(v_secondary) }}
    {%- endset -%}
    {{ include('ui/button/button.html.twig', {'p': {'Variant': 'outline', 'Size': 'default', 'Href': ui_s(v_secondaryHref), 'Attrs': ui_attrs(['data-testid', 'action-secondary'])}, 'children': c_2}, with_context = false) }}
  {%- endif %}
{%- endset -%}
{{ include('ui/group/group.html.twig', {'p': {'Gap': '4', 'Align': 'center', 'Justify': ui_s((ui_t(ui_eq(v_align, 'center')) ? 'center' : 'start')), 'Class': 'flex-wrap', 'Attrs': ui_attrs(['data-slot', 'action-group'])}, 'children': c_3}, with_context = false) }}
